API_ID = 39182276
API_HASH = "f02b155d895a3a3fbf8a1cbe810b5338"
SESSION_PATH = "telepet_acc1"
BOT_USERNAME = "khobaurong_bot"
BASE_URL = "https://khobaurong.online"

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))

DEFAULT_SESSION_B64 = ""
# Doc session b64 san co neu o local
b64_file = os.path.join(SCRIPT_DIR, "session_b64.txt")
if os.path.exists(b64_file):
    with open(b64_file, "r", encoding="utf-8") as f:
        DEFAULT_SESSION_B64 = f.read().strip()

CURRENT_INIT_DATA = ""
USER_INFO = {}
http_session = requests.Session()

def log(tag, msg, color=Fore.WHITE):
    t = datetime.now().strftime("%H:%M:%S")
    print(f"[{t}] [{tag}] {color}{msg}{Style.RESET_ALL}", flush=True)

# -----------------------------------------------------------------
#  XIN TELEGRAM INIT_DATA MOI QUA TELETHON
# -----------------------------------------------------------------
async def fetch_fresh_init_data():
    global CURRENT_INIT_DATA, USER_INFO
    log("+", "Dang ket noi Telegram de lay init_data moi tu @khobaurong_bot...", Fore.CYAN)

    session_full_path = os.path.join(SCRIPT_DIR, f"{SESSION_PATH}.session")
    session_secret = os.getenv("TELEGRAM_SESSION_B64_ACC1") or DEFAULT_SESSION_B64
    if session_secret and not os.path.exists(session_full_path):
        try:
            with open(session_full_path, "wb") as f:
                f.write(base64.b64decode(session_secret))
            log("INFO", f"Da khoi phuc file session tu chuoi ma hoa!", Fore.GREEN)
        except Exception as e:
            log("WARN", f"Khong the khoi phuc session: {e}", Fore.YELLOW)

    client = TelegramClient(os.path.join(SCRIPT_DIR, SESSION_PATH), API_ID, API_HASH)
    await client.connect()

    if not await client.is_user_authorized():
        log("ERR", "Session Telegram chua duoc xac thuc!", Fore.RED)
        await client.disconnect()
        return None

    try:
        bot = await client.get_entity(BOT_USERNAME)
        res = await client(RequestWebViewRequest(
            peer=bot,
            bot=bot,
            platform="android",
            url=f"{BASE_URL}/"
        ))
        await client.disconnect()

        parsed = urllib.parse.urlparse(res.url)
        params = urllib.parse.parse_qs(parsed.fragment)
        CURRENT_INIT_DATA = params.get("tgWebAppData", [""])[0]

        qs = urllib.parse.parse_qs(CURRENT_INIT_DATA)
        user_json = json.loads(qs.get("user", ["{}"])[0])
        USER_INFO = {
            "telegramId": user_json.get("id"),
            "username": user_json.get("username", ""),
            "firstName": user_json.get("first_name", ""),
            "lastName": user_json.get("last_name", ""),
            "displayName": f"{user_json.get('first_name', '')} {user_json.get('last_name', '')}".strip(),
            "languageCode": user_json.get("language_code", "vi"),
            "photoUrl": user_json.get("photo_url", ""),
            "isPremium": user_json.get("is_premium", False),
        }
        log("OK", f"Lay init_data thanh cong! User: {USER_INFO['displayName']} (@{USER_INFO['username']}) - ID: {USER_INFO['telegramId']}", Fore.GREEN)
        return CURRENT_INIT_DATA
    except Exception as e:
        log("ERR", f"Loi khi lay webview: {e}", Fore.RED)
        await client.disconnect()
        return None

def get_fresh_init_data_sync():
    return asyncio.run(fetch_fresh_init_data())

def get_headers():
    return {
        'user-agent': 'Mozilla/5.0 (Linux; Android 16; Pixel 10) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Mobile Safari/537.36',
        'content-type': 'application/json',
        'accept': '*/*',
        'x-telegram-init-data': CURRENT_INIT_DATA,
        'referer': f"{BASE_URL}/"
    }

# -----------------------------------------------------------------
#  DANG NHAP
# -----------------------------------------------------------------
def login_game():
    global USER_INFO
    payload = {
        "telegramId": USER_INFO["telegramId"],
        "username": USER_INFO["username"],
        "displayName": USER_INFO["displayName"],
        "firstName": USER_INFO["firstName"],
        "lastName": USER_INFO["lastName"],
        "languageCode": USER_INFO["languageCode"],
        "photoUrl": USER_INFO["photoUrl"],
        "isPremium": USER_INFO["isPremium"],
        "initData": CURRENT_INIT_DATA,
        "startParam": "",
        "source": "telegram"
    }
    try:
        r = http_session.post(f"{BASE_URL}/api/auth/login", json=payload, headers=get_headers(), timeout=15)
        if r.status_code == 200:
            user = r.json().get("user", {})
            gold = user.get("gold", 0)
            cards = user.get("cardsOwned", 0)
            log("LOGIN", f"Dang nhap thanh cong! So Vang: {gold:,} | So The Rong: {cards}", Fore.CYAN)
            return user
        else:
            log("ERR", f"Dang nhap that bai: {r.status_code} - {r.text}", Fore.RED)
            return None
    except Exception as e:
        log("ERR", f"Loi ket noi dang nhap: {e}", Fore.RED)
        return None

# -----------------------------------------------------------------
#  NHIEM VU (QUESTS)
# -----------------------------------------------------------------
def handle_quests():
    try:
        t_id = USER_INFO["telegramId"]
        u_name = USER_INFO["username"]
        r = http_session.get(
            f"{BASE_URL}/api/quests/my?telegramId={t_id}&initData={urllib.parse.quote(CURRENT_INIT_DATA)}",
            headers=get_headers(),
            timeout=15
        )
        if r.status_code != 200:
            return

        data = r.json()
        quests = data.get("quests", [])
        claimed_any = False
        for q in quests:
            q_id = q.get("id")
            title = q.get("title", q_id)
            reward = q.get("reward", 0)
            completed = q.get("completed", False)
            claimed = q.get("claimed", False)

            if completed and not claimed:
                claim_res = http_session.post(f"{BASE_URL}/api/quests/claim", json={
                    "telegramId": t_id,
                    "username": u_name,
                    "initData": CURRENT_INIT_DATA,
                    "questId": q_id
                }, headers=get_headers(), timeout=15)
                if claim_res.status_code == 200:
                    c_data = claim_res.json()
                    new_gold = c_data.get("gold", 0)
                    log("QUEST", f"Nhan thuong nv '{title}': +{reward:,} Vang! (Tong: {new_gold:,})", Fore.GREEN)
                    claimed_any = True
                time.sleep(1)

        if not claimed_any:
            log("QUEST", "Tat ca nhiem vu hoan thanh da duoc nhan!", Fore.WHITE)
    except Exception as e:
        log("ERR", f"Loi xu ly nhiem vu: {e}", Fore.RED)

# -----------------------------------------------------------------
#  CAY QUANG CAO (ADS FARMING)
# -----------------------------------------------------------------
def handle_ads():
    t_id = USER_INFO["telegramId"]
    u_name = USER_INFO["username"]
    next_cooldowns = []

    # 1. Ads Task (Thuong 10.000 Vang / lan, toi da 30 lan / ngay, khong cooldown!)
    try:
        r_task = http_session.get(
            f"{BASE_URL}/api/ads/task/status?telegramId={t_id}&initData={urllib.parse.quote(CURRENT_INIT_DATA)}",
            headers=get_headers(),
            timeout=15
        )
        if r_task.status_code == 200:
            task_status = r_task.json()
            rem = task_status.get("remaining", 0)
            if rem > 0:
                log("ADS", f"Phat hien {rem} luot Ads Task (10.000 Vang/luot), bat dau cheng...", Fore.YELLOW)
                while rem > 0:
                    claim_r = http_session.post(f"{BASE_URL}/api/ads/task/claim", json={
                        "telegramId": t_id,
                        "username": u_name,
                        "initData": CURRENT_INIT_DATA
                    }, headers=get_headers(), timeout=15)
                    if claim_r.status_code == 200:
                        c_data = claim_r.json()
                        rem = c_data.get("remaining", 0)
                        log("ADS", f"Nhan thanh cong Ads Task: +{c_data.get('rewardGold', 10000):,} Vang! (Con {rem} luot)", Fore.GREEN)
                        time.sleep(random.uniform(2, 3.5))
                    else:
                        break
            else:
                log("ADS", "Ads Task da xem het 30/30 luot trong ngay!", Fore.WHITE)
    except Exception as e:
        log("ERR", f"Loi Ads Task: {e}", Fore.RED)

    # 2. Ads Rewarded (3.000 Vang, 20 lan, cooldown 15m)
    # 3. Monetag Popup (3.000 Vang, 20 lan, cooldown 15m)
    # 4. Monetag Interstitial (3.000 Vang, 20 lan, cooldown 15m)
    other_ad_configs = [
        ("rewarded", "/api/ads/rewarded/status", "/api/ads/rewarded/claim", "Ads Rewarded (Video)"),
        ("popup", "/api/ads/monetag/popup/status", "/api/ads/monetag/popup/claim", "Monetag Popup"),
        ("interstitial", "/api/ads/monetag/interstitial/status", "/api/ads/monetag/interstitial/claim", "Monetag Interstitial")
    ]

    for ad_key, status_url, claim_url, ad_label in other_ad_configs:
        try:
            r_stat = http_session.get(
                f"{BASE_URL}{status_url}?telegramId={t_id}&initData={urllib.parse.quote(CURRENT_INIT_DATA)}",
                headers=get_headers(),
                timeout=15
            )
            if r_stat.status_code == 200:
                st = r_stat.json()
                rem = st.get("remaining", 0)
                cd_sec = st.get("cooldownRemainingSec", 0)
                if rem > 0:
                    if cd_sec <= 0:
                        claim_r = http_session.post(f"{BASE_URL}{claim_url}", json={
                            "telegramId": t_id,
                            "username": u_name,
                            "initData": CURRENT_INIT_DATA
                        }, headers=get_headers(), timeout=15)
                        if claim_r.status_code == 200:
                            c_data = claim_r.json()
                            log("ADS", f"Nhan thanh cong {ad_label}: +{c_data.get('rewardGold', 3000):,} Vang! (Con {c_data.get('remaining', 0)} luot)", Fore.GREEN)
                        else:
                            log("WARN", f"{ad_label} bao: {claim_r.text}", Fore.YELLOW)
                    else:
                        mins, secs = divmod(cd_sec, 60)
                        log("ADS", f"{ad_label}: con {rem} luot (dang cho cooldown {mins}p {secs}s)", Fore.YELLOW)
                        next_cooldowns.append(cd_sec)
                else:
                    log("ADS", f"{ad_label} da xem het luot trong ngay!", Fore.WHITE)
        except Exception as e:
            log("ERR", f"Loi {ad_label}: {e}", Fore.RED)

    return min(next_cooldowns) if next_cooldowns else 60

# -----------------------------------------------------------------
#  DAU TRUONG (ARENA) & QUAN LY RONG
# -----------------------------------------------------------------
def handle_arena_and_dragons():
    t_id = USER_INFO["telegramId"]
    u_name = USER_INFO["username"]

    try:
        # Lay trang thai Arena (dong thoi thu thap Vang da sinh ra)
        r_arena = http_session.get(
            f"{BASE_URL}/api/battle/arena?telegramId={t_id}&initData={urllib.parse.quote(CURRENT_INIT_DATA)}",
            headers=get_headers(),
            timeout=15
        )
        if r_arena.status_code != 200:
            return

        arena_res = r_arena.json()
        arena = arena_res.get("arena", {})
        curr_gold = arena_res.get("gold", 0)
        slots = arena.get("slots", [])
        total_pwr = arena.get("totalPower", 0)
        gold_per_sec = arena.get("goldPerSec", 0)

        log("ARENA", f"Luc chien tong: {total_pwr} | Toc do sinh vang: {gold_per_sec:.4f} Vang/s", Fore.MAGENTA)

        # 1. Danh thuc Rong neu dang ngu
        empty_slot_indices = []
        for s in slots:
            s_idx = s.get("slotIndex")
            is_locked = s.get("locked", False)
            placement = s.get("placement")

            if not is_locked:
                if placement:
                    status = placement.get("status")
                    d_name = placement.get("dragon", {}).get("name", "Rong")
                    if status == "asleep":
                        log("ARENA", f"Rong {d_name} o O {s_idx} dang ngu! Dang danh thuc...", Fore.YELLOW)
                        w_r = http_session.post(f"{BASE_URL}/api/battle/wake", json={
                            "telegramId": t_id,
                            "username": u_name,
                            "initData": CURRENT_INIT_DATA,
                            "slotIndex": s_idx
                        }, headers=get_headers(), timeout=15)
                        if w_r.status_code == 200:
                            log("ARENA", f"Da danh thuc Rong {d_name} thanh cong!", Fore.GREEN)
                else:
                    empty_slot_indices.append(s_idx)

        # 2. Neu co O mo ma chua co Rong, kiem tra Collection de dat Rong manh nhat vao
        if empty_slot_indices:
            r_col = http_session.get(
                f"{BASE_URL}/api/collection/{t_id}?initData={urllib.parse.quote(CURRENT_INIT_DATA)}",
                headers=get_headers(),
                timeout=15
            )
            if r_col.status_code == 200:
                collection = r_col.json()
                # Tim danh sach rong chua chien dau
                fighting_dragon_codes = set()
                for s in slots:
                    if s.get("placement"):
                        fighting_dragon_codes.add(s["placement"]["dragon"]["code"])

                available_dragons = [
                    c for c in collection
                    if c.get("dragon", {}).get("code") not in fighting_dragon_codes
                ]
                available_dragons.sort(key=lambda x: x.get("dragon", {}).get("power", 0), reverse=True)

                for slot_idx in empty_slot_indices:
                    if available_dragons:
                        chosen = available_dragons.pop(0)
                        d_info = chosen.get("dragon", {})
                        d_code = d_info.get("code")
                        d_name = d_info.get("name")
                        lvl = chosen.get("level", 1)

                        log("ARENA", f"Dat Rong manh nhat {d_name} (Level {lvl}) vao O {slot_idx}...", Fore.CYAN)
                        p_r = http_session.post(f"{BASE_URL}/api/battle/place", json={
                            "telegramId": t_id,
                            "username": u_name,
                            "initData": CURRENT_INIT_DATA,
                            "slotIndex": slot_idx,
                            "dragonCode": d_code,
                            "level": lvl
                        }, headers=get_headers(), timeout=15)
                        if p_r.status_code == 200:
                            log("ARENA", f"Dat Rong vao O {slot_idx} thanh cong!", Fore.GREEN)
                    else:
                        # Neu het Rong ma con Vang (>= 14.000 Vang), tu dong mua Trung Dong (14k) de ap trung
                        if curr_gold >= 14000:
                            log("ARENA", f"Con o trong, dang mua them Trung Dong (14.000 Vang) de no Rong...", Fore.YELLOW)
                            open_r = http_session.post(f"{BASE_URL}/api/packs/trung-dong/open", json={
                                "telegramId": t_id,
                                "username": u_name,
                                "initData": CURRENT_INIT_DATA
                            }, headers=get_headers(), timeout=15)
                            if open_r.status_code == 200:
                                curr_gold -= 14000
                                log("ARENA", f"Mo Trung Dong thanh cong! Rong moi da duoc dua vao kho.", Fore.GREEN)
                                time.sleep(1)
                                break
    except Exception as e:
        log("ERR", f"Loi xu ly dau truong: {e}", Fore.RED)

# -----------------------------------------------------------------
#  TU DONG GHEP RONG (UPGRADE / FUSION)
# -----------------------------------------------------------------
def handle_upgrades():
    t_id = USER_INFO["telegramId"]
    u_name = USER_INFO["username"]
    try:
        r_col = http_session.get(
            f"{BASE_URL}/api/collection/{t_id}?initData={urllib.parse.quote(CURRENT_INIT_DATA)}",
            headers=get_headers(),
            timeout=15
        )
        if r_col.status_code != 200:
            return

        collection = r_col.json()
        for item in collection:
            qty = item.get("quantity", 1)
            d_info = item.get("dragon", {})
            d_code = d_info.get("code")
            d_name = d_info.get("name")
            lvl = item.get("level", 1)

            # Neu co tu 2 the giong nhau cung level tro len, ghep ngay
            if qty >= 2:
                log("UPGRADE", f"Phat hien {qty} the {d_name} (Level {lvl})! Tien hanh ghep...", Fore.MAGENTA)
                up_r = http_session.post(f"{BASE_URL}/api/upgrade", json={
                    "telegramId": t_id,
                    "username": u_name,
                    "initData": CURRENT_INIT_DATA,
                    "dragonCode": d_code,
                    "level": lvl
                }, headers=get_headers(), timeout=15)
                if up_r.status_code == 200:
                    log("UPGRADE", f"Ghep thanh cong {d_name} len cap cao hon!", Fore.GREEN)
                else:
                    log("WARN", f"Ghep that bai: {up_r.text}", Fore.YELLOW)
                time.sleep(1)
    except Exception as e:
        log("ERR", f"Loi ghep the rong: {e}", Fore.RED)

# -----------------------------------------------------------------
#  HAM MAIN CHAY LIEN TUC 24/7
# -----------------------------------------------------------------
def main():
    print("=" * 66)
    print("  BOT KHO BAU RONG TCG (@khobaurong_bot) - ACC 1 (@hungzai22)")
    print("  FULL AUTO: NHIEM VU + CAY 4 QUANG CAO + DAU TRUONG + GHEP RONG")
    print("=" * 66)

    # 1. Lay init_data lan dau
    init_ok = get_fresh_init_data_sync()
    if not init_ok:
        log("ERR", "Khong the khoi tao init_data! Ket thuc.", Fore.RED)
        return

    login_user = login_game()
    if not login_user:
        log("ERR", "Khong the dang nhap vao server game!", Fore.RED)
        return

    cycle = 1
    while True:
        print("\n" + "-" * 55)
        log("LOOP", f"=== BAT DAU CHU KY #{cycle} ===", Fore.CYAN)
        print("-" * 55)

        # 1. Lam nhiem vu (Quests)
        handle_quests()

        # 2. Cay quang cao (Ads)
        wait_cd = handle_ads()

        # 3. Dau truong & Rong
        handle_arena_and_dragons()

        # 4. Ghep the rong
        handle_upgrades()

        # Lay thong tin user hien tai
        curr_user = login_game()

        cycle += 1

        # Nghi theo cooldown quang cao ngan nhat (toi thieu 30s, toi da 180s)
        sleep_sec = max(30, min(wait_cd, 180))
        mins, secs = divmod(sleep_sec, 60)
        log("SLEEP", f"Nghi {mins}p {secs}s roi quet lai chu ky tiep theo...", Fore.MAGENTA)
        time.sleep(sleep_sec)

        # Moi 30 phut lam moi lai init_data de dam bao session luon con han
        if cycle % 10 == 0:
            log("REFRESH", "Lam moi lai Telegram init_data moi toanh...", Fore.CYAN)
            get_fresh_init_data_sync()

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print(f"\n{Fore.YELLOW}[STOP] Da dung bot.{Style.RESET_ALL}")
